window.BOOK_TEXT = [
  {"id":"mukdash","t":"מוקדש","s":"","p":6,"kind":"הקדשה","blocks":[{"t":"p","x":"היום בבוקר חציתי את ארץ הפלאות בדרכי לעבודה. איחלתי בוקר טוב לאיילי חג המולד, חיבקתי לשלום את הפיראטית ונתתי שושנה לנסיך הקטן."},{"t":"p","x":"ואז, ממש לפני שנכנסתי לאוטו, ראיתי חד קרן יפה כזו, בת 12 או 13 יושבת על נדנדת עץ ובוכה. לחד קרן הזו, עם הקשת בענן שהיא ציירה לעצמה על הלחי, ועכשיו היא מרוחה, היה יום קצת אחר."},{"t":"p","x":"סגרתי את הדלת וניגשתי לחד קרן. התיישבתי לידה. התנדנדנו כמה רגעים שקטים קדימה ואחורה. היא משכה קצת באף והמבטים שלנו נפגשו בשלולית הקטנה שעל הרצפה."},{"t":"p","x":"\"איך קוראים לך, חד קרן?\"","c":"said"},{"t":"p","x":"\"דנה\" היא אמרה.","c":"said"},{"t":"p","x":"\"ולמה את בוכה?\"","c":"said"},{"t":"p","x":"\"שכחתי את הכנפיים בבית. אני לא יכולה להיות חד קרן בלי כנפיים\".","c":"said"},{"t":"p","x":"טיפה נוספת נפלה לשלולית.","c":"said"},{"t":"p","x":"\"דנה, את לא צריכה כנפיים\"","c":"said"},{"t":"p","x":"\"אנחנו לא רוצים אותך בשמיים, אנחנו רוצים אותך כאן איתנו, על האדמה\".","c":"said"},{"t":"p","x":"היא חייכה והמשיכה לדרכה."},{"t":"p","x":"הרבה שנים לקח לי ללמוד להתמודד עם ארץ הפלאות הזו, שמסתיימת ומתחילה עם דנה במעבר חצייה. תמיד היא צפה אצלי בהמון געגועים ובדמעות של פורים."}]},
  {"id":"izun-temperaturot","t":"איזון טמפרטורות","s":"","p":8,"kind":"שיר","blocks":[{"t":"st","l":["באותו הבוקר רוחנו להטה,","הצלפנו האחד בשניה בחוזקה."]},{"t":"st","l":["התרוקנו, רוקנו להבות של טינה.","הלכנו לישון בקצוות המיטה."]},{"t":"st","l":["כשיצאת להפשיר, הטמפרטורה צנחה,","הבנה חדה את גופי פילחה."]},{"t":"st","l":["לא אצליח להתחמם מגופך יותר לעולם.","הכי קל להתחבק כשקר."]}]},
  {"id":"n593","t":"593","s":"","p":9,"kind":"שיר","blocks":[{"t":"st","l":["חמש מאות תשעים ושלושה ימים עמדתי וספרתי אותה.","נאה, אלומה.","עלומה."]},{"t":"st","l":["היא סיפור אהבה.","קטן כזה, של כמה שורות.","לפעמים קצרות, לפעמים ארוכות."]},{"t":"st","l":["קול רחוק שבקושי נשמע מהדהד לי בראש.","אינו מרפה.","מרפא."]},{"t":"st","l":["היא סיפור אהבה.","ארוך כזה של כמה פסקאות.","לא מנוקדות, ללא תחיליות."]},{"t":"st","l":["עננה כחולה נגעה בה לפני שנים.","המים של חייה זורמים.","חמים."]},{"t":"st","l":["היא סיפור אהבה.","בהיר כזה, כמו מקלדת ללא אותיות.","עם כסת אדומה ונוצה לידה."]},{"t":"st","l":["הימים נוסעים, היא מגיעה מרחוק","מגיעה למקומות,","תהומות."]},{"t":"st","l":["היא סיפור אהבה.","מוזר כזה, על זוגיות מאוחרת,","שמאמינה כי אפשר גם אחרת."]}]},
  {"id":"yuval-1","t":"אני אצל יובל","s":"פרק 1","p":11,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"\"חכי! אל תשלחי!\" צעקתי מהצד השני של החדר. זה היה מאוחר מידי. \"תמחקי! תמחקי!\" רצתי לקראתה לתפוס את הטלפון. שני הסימנים הכחולים שצמודים להודעת התמונה הבהירו לי שאין דרך חזרה."},{"t":"p","x":"זה בחוץ. שנה הצלחתי להסתיר את זה. \"את מבינה מה עשית?! זהו, זה נגמר!\""},{"t":"p","x":"עמדתי מולה. אור הירח האיר את הסימנים הכחולים שהשארתי על פניה הדומעות."}]},
  {"id":"ahava-regit","t":"אהבה רגעית","s":"","p":12,"kind":"סיפור","blocks":[{"t":"p","x":"הדלתות נסגרו."},{"t":"p","x":"המעלית התחילה לעלות."},{"t":"p","x":"הסתכלתי על המספרים מנסה להזכר היכן חניתי. בקומה שש נפתחו הדלתות והיא נכנסה."},{"t":"p","x":"אני זוכר את המבט המופתע שלה, נכנסת למעלית ואין אף קומה לחוצה. אולי המבט לא היה מופתע, אולי הוא היה מבט של פחד."},{"t":"p","x":"היא לחצה על קומה מינוס שלוש אז מיד לחצתי על קומה מינוס ארבע."},{"t":"p","x":"הסתכלתי עליה דרך המראה בצד. למה אף פעם אין לי את האומץ אפילו להגיד שלום, או לשאול לשלומה."},{"t":"p","x":"המעלית הישנה רעדה והתחילה לרדת. הספירה לאחור של הקומות הכבידה עלי."},{"t":"p","x":"ריח הפריחה מהשיער שלה הטריף לי את כל החושים. יכולתי להרגיש אותו זורם מהאף, אל תוך מחזור הדם שלי ואל קצות האצבעות."},{"t":"p","x":"הגענו לקומה מינוס שלוש."},{"t":"p","x":"שוב היא תלך ואני אבלה את שארית השבוע מצטער על הדקה הזו שעברה ולא תחזור. כמה מחשבות רצו לי בראש באותו רגע. האם לצאת אחריה? האם להגיד לה איך קוראים לי? אולי לבקש ממנה עזרה?"},{"t":"p","x":"כל כך הרבה כיוונים, שלא הפנמתי בכלל שהיא לוחצת בטירוף על כפתור פתיחת הדלתות כי הן לא נפתחו."},{"t":"p","x":"פתאום הבנתי שאנחנו במצוקה, ואני עומד ולא עושה כלום. \"היי, נראה לי שהמעלית נתקעה\". איזה משפט טיפשי, חשבתי לעצמי... הרי היא בטח כבר יודעת את זה. היא אפילו לא הסתובבה ורק המשיכה ללחוץ על הכפתור."},{"t":"p","x":"\"אני אתקשר למכבי האש\", מלמלתי והוצאתי את הטלפון. לא היתה קליטה."},{"t":"p","x":"\"היי, קוראים לי נתי. תוכלי אולי לבדוק אם יש לך קליטה?\""},{"t":"p","x":"\"היי, אני ענת. נגמרה לי הבטרייה לפני איזה חצי שעה ושכחתי את המטען באוטו. בגלל זה ירדתי למטה, אני גרה כאן\""},{"t":"p","x":"\"גם אני גר כאן, בדירה 14. כבר נפגשנו במעלית לפני כמה חודשים\"."},{"t":"p","x":"חייכתי בעדינות. היא הסתובבה לכיווני"},{"t":"p","x":"\"מה נעשה?\""},{"t":"p","x":"אף פעם לא הייתי ה\"גבר\" הזה, שיודע לשלוף את הלדרמן מהתיק או זה שמנסה לפתוח את הדלתות עם השיניים. התלבטתי אם להפוך לכזה, או להמשיך להיות אני."},{"t":"p","x":"\"זה נראה כמו קצר בחשמל\" מלמלתי בביטחון."},{"t":"p","x":"\"שום דבר לא מגיב\"."},{"t":"p","x":"תאורת החירום הבהבה."},{"t":"p","x":"\"סיגריה?\" שאלה אותי ענת בזמן שהיא שולפת סיגריה אלקטרונית מהכיס. ישבנו על הרצפה, מעשנים בתורות עד שסיימנו את הטבק."},{"t":"p","x":"\"כמה זמן אנחנו כבר פה?\" שאלה אותי."},{"t":"p","x":"\"40 דקות, כבר רבע לשתיים עשרה\"."},{"t":"p","x":"\"דווקא נחמד לי\" היא אמרה,"},{"t":"p","x":"\"חוץ מזה שנהיה קצת מחניק וממש רציתי כבר ללכת לישון\" לא שמעתי את הסוף של המשפט שלה."},{"t":"p","x":"\"נהיה לי חם ממש, וקשה לי לנשום\" היא מלמלה, שוכבת על הרצפה ואני מנגב לה את הזיעה מהמצח עם החולצה שלי."},{"t":"p","x":"\"אל תדברי ענתי, אנחנו צריכים את האוויר עד שיבואו לחלץ אותנו\"."},{"t":"p","x":"חזרתי להכרה בשש בבוקר בבית חולים. \"איפה ענת? זו שהיתה איתי במעלית\" שאלתי את יוני שישב על הכורסה לידי."},{"t":"p","x":"\"איזו ענת? מכבי האש חילצו אותך לבד מהמעלית\"."}]},
  {"id":"meyabesh-dmaot","t":"מייבש דמעות","s":"","p":15,"kind":"שיר","blocks":[{"t":"st","l":["היא לא רוצה להתחפש למה שאינה,","לאשה חזקה עם הבעה קשוחה."]},{"t":"gap"},{"t":"st","l":["היא לא רוצה לנעול עקבים וחליפות,","לעטות מסכה של פנים זועפות."]},{"t":"st","l":["היא לא רוצה לעטוף רגשות","בצבעים כהים ומייבש דמעות."]},{"t":"gap"},{"t":"st","l":["היא רוצה לפשוט את השמלה השחורה,","שמכריחים אותה ללבוש לעבודה."]},{"t":"st","l":["להתחיל להתחפש לעצמה.","לדעת שהיא יכולה."]},{"t":"gap"},{"t":"st","l":["להסתובב בביטחון בחברה","גם עם השמלה הורודה."]},{"t":"st","l":["לדבר בשקט, מבלי להתפרץ","בלי הצורך לצעוק חזק ולשחק."]},{"t":"st","l":["לחייך כשבא,","להביע דעה."]},{"t":"st","l":["היא לא רוצה להתחפש למה שאינה","רוצה להיות שווה."]}]},
  {"id":"yuval-2","t":"אני אצל יובל","s":"פרק 2","p":16,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"היא ניגבה את פניה. \"זה נגמר!\" היא אמרה והדליקה את מנורת השולחן הלבנה."},{"t":"p","x":"לא ידעתי איך להגיב. הטלפון שלה רטט ללא הפסקה ביד שלי. התמונה הישנה, יושבת על הכתפיים הרחבות של אבא שלה הופיעה על הטלפון. ניתקתי בגסות. הידיים שלי נוטפות זיעה, הגוף שלי קפוא. תמיד ידעתי לנווט את התקפי הזעם שלי היטב. והיא ידעה להכיל אותם. ולהסתיר. עם הרבה מייקאפ ופודרה. הרגשתי שהיא שומרת עלי. מבינה. ופתאום זה נשבר. נגמר. הטלפון רטט שוב, הגשתי לה אותו בכניעה. \"אבא, בוא לקחת אותי\" היא לחשה. \"אני אצל יובל\". יכולתי לשמוע אותו צועק מהצד השני. ואותה שותקת."},{"t":"p","x":"\"אני מצטערת\", מלמלתי. \"מגיעה לך מישהי יותר טובה ממני\"."}]},
  {"id":"amok-bamegira","t":"עמוק במגירה","s":"","p":17,"kind":"סיפור","blocks":[{"t":"p","x":"\"שימי אותו חזרה בקופסה עכשיו!\" צעקתי עליה מלמטה. ליאן חפנה אותו בשתי הידיים ושמה אותו בקופסה השחורה."},{"t":"p","x":"מאחוריי שיירת המכוניות לא הפסיקה לצפצף."},{"t":"p","x":"רצתי בבהלה."},{"t":"p","x":"הראש שלי התפוצץ. הרגשתי כאילו מישהו לוחץ לי את המוח בצבת ענקי. לחיצה חזקה כזו שלא נותנת לי להשתחרר אבל לא מספיק חזקה כדי למעוך אותי למוות."},{"t":"p","x":"פעם אחרונה שחוויתי לחץ כזה בראש היה כשלקחתי ריטלין לפני מבחני הלשכה."},{"t":"p","x":"ליאן, שעבדה איתי כמתמחה במשרד, תמיד צחקה על חוסר היכולת שלי להתנסח. \"איך תהיה עורך דין אם אתה לא יכול לחבר שלושה משפטים לטענה לוגית?\" היתה עוקצת."},{"t":"p","x":"לקח זמן להסביר לה שהמחשבות שלי רצות יותר מהר ממה שהפה שלי מסוגל לבטא. אז לוקח לו לפעמים שלושה או ארבעה משפטים עד שהוא מדייק את עצמו."},{"t":"p","x":"את הקופסה השחורה קיבלתי במתנה מיעלי, החברה הראשונה שלי. קופסא כזו שעומדת תמיד על השידה, פתוחה ומלאה בחשבונות, מפתחות ושאריות של עפרונות."},{"t":"p","x":"קופסא רגילה, אבל מאוד מאוד שחורה."},{"t":"p","x":"כשיעלי עזבה, דחפתי את הקופסא לארגז הבגדים שלה. הרגשתי שהיא שייכת לה אחרי כל הזמן שבילינו ביחד."},{"t":"p","x":"בוקר אחרי, מצאתי את הקופסא מחוץ לדלת."},{"t":"p","x":"הרמתי ודחפתי אותה עמוק עמוק במגירה האחרונה. ידעתי שיהיה לי קשה לחזור להתפקס אם אחשוב על מה שנמצא בתוכה. לאורך השנים הדחקתי את הקופסא ואת מה שהשארתי סגור בתוכה."},{"t":"p","x":"המשכתי בחיי. חברות, בנות זוג, סטוצים, תקופת רווקות ארוכה, לימודים ואז ליאן."},{"t":"p","x":"ליאן תמיד ישבה שם בלימודים, בשורה העליונה, כותבת וכותבת את כל החומר בעט פיילוט כחולה. אף פעם לא התייחסתי אליה יותר מידי, אבל תמיד יכולתי להריח את ריח הפריחה משאריות השמפו שלה בשיעורי הבוקר."},{"t":"p","x":"בשנה האחרונה כבר עברנו לגור ביחד, חיים אחד בתוך השניה, נושם אותה ופורח כל בוקר."},{"t":"p","x":"\"אני אוהבת אותך\", היתה לוחשת לי באוזן כל לילה לפני השינה, ואני הייתי מקשיב, מסתובב, עושה את עצמי ישן ונרדם."},{"t":"p","x":"\"הארון שלך מבולגן כמו המילים שאתה מוציא, תן לי לסדר אותו\". ליאן היתה מציעה לי כל שבוע ואני הייתי אוסר עליה לגעת לי בבגדים ובמילים."},{"t":"p","x":"זה היה יום חורפי, הגשם ירד באלכסון, והמטרייה שלי התהפכה ברגע שיצאתי מהמשרד."},{"t":"p","x":"נכנסתי הביתה, הטלוויזיה פעלה על איזה ערוץ לא רלוונטי ושאריות של פסטה קרה עמדו על השולחן."},{"t":"p","x":"\"ליאן!\" קראתי לה, \"חזרתי, באה לסיגריה למטה?\" הריטואל הקבוע שלנו אחרי ימים ארוכים בבית המשפט. \"תרד\", היא ענתה לי מחדר השינה. \"תכף אצטרף\". לקחתי את המרלבורו לייט וירדתי לרחוב."},{"t":"p","x":"הדלקתי את הסיגריה מתחת לגגון שבצד השני של הרחוב, הסתכלתי למעלה על הצללית של ליאן בחלון של החדר שינה שלנו."},{"t":"p","x":"הווילון זז."},{"t":"p","x":"\"תגיד\", ליאן מסתכלת עלי למטה מהחלון \"מה זה?\" האור ממנורת הרחוב סינוור אותי, אבל יכולתי לראות שהיא מחזיקה משהו ביד."},{"t":"p","x":"ירדתי לכביש כדי לראות יותר טוב, הגשם כיבה לי את הסיגריה."},{"t":"p","x":"\"שימי אותו חזרה בקופסא עכשיו!\" צעקתי עליה מלמטה. ליאן חפנה אותו בשתי הידיים ושמה אותו בקופסא השחורה."},{"t":"p","x":"מאחורי שיירת המכוניות לא הפסיקה לצפצף. רצתי מהמקום בבהלה."},{"t":"p","x":"התמונה של ליאן בחלון, מחזיקה את הלב שלי בשתי הידיים, לא יוצאת לי מהראש."}]},
  {"id":"meri-an","t":"מרי-אן","s":"","p":20,"kind":"שיר","blocks":[{"t":"st","l":["רקדתי היום","עם אשתי בסלון,","הילדים עדיין לא הלכו לישון."]},{"t":"st","l":["התחבקנו.","הגברנו צלילים,","ניסינו להימנע","מלשמוע את עצמנו חושבים."]},{"t":"st","l":["שלוש מאות שניות וארבעים","נכחנו רק כאן.","שנינו.","עם לאונרד ומרי-אן."]},{"t":"st","l":["רקדתי היום","עם אשתי בסלון,","הילדים כבר הלכו לישון."]},{"t":"st","l":["העולם עצר לרגע,","היינו האחד בשניה.","שחררנו. התרנו לעצמנו","להתאהב בתקופה."]},{"t":"st","l":["נפגשנו,","כשהיינו כמעט צעירים","בשדות חוף הים","הפתוחים."]},{"t":"st","l":["רקדתי היום","עם אשתי בסלון,","לרגע התאהבנו שוב ממבט ראשון."]}]},
  {"id":"avanim-mishtalvot","t":"אבנים משתלבות","s":"","p":22,"kind":"סיפור קצר","blocks":[{"t":"p","x":"נפלתי אתמול על המדרכה."},{"t":"p","x":"בנס לא שברתי את הרגל."},{"t":"p","x":"הרמתי את עצמי לאט, הקרסול נקוע בוודאות, יד ימין מדממת קצת מהשפשוף באבנים המשתלבות."},{"t":"p","x":"קרע קטן במכנסים וכפכף הווייאנס שסיים את דרכו."},{"t":"p","x":"\"סאמק\", סיננתי לעצמי כשניסיתי ללכת כמה צעדים עם רגל אחת יחפה וחבולה."},{"t":"p","x":"עצרתי."},{"t":"p","x":"הסתובבתי אחורה להסתכל במה בעצם נתקלתי."},{"t":"p","x":"לרגע היה נדמה לי ששכבת שם על הרצפה."},{"t":"p","x":"שפשפתי את העיניים, ונעלמת."},{"t":"p","x":"איפה ששכבת נשאר רק כתם של מים שנזל מצינור הניקוז של המזגן הרועש של הפיצריה."},{"t":"p","x":"אוף."},{"t":"p","x":"חזרת לבקר ופיספסתי אותך."},{"t":"p","x":"הדקה הקצרה הזו, של ערבוב המציאות, תפסה אותי לא מוכן."},{"t":"p","x":"אוף. כמה שאני מתגעגע אליך."}]},
  {"id":"yuval-m1","t":"אני אצל יובל","s":"פרק מינוס 1","p":23,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"גדלתי עם יובל. היא נכנסה אלינו הביתה כשהייתי בת 5 והיא היתה בת 9. יפה כזו, ג'ינג'ית עם שיער ארוך אסוף ברישול. אבא שלי חיבק את אמא של יובל ברגע שהיא נכנסה בדלת. חיבוק חזק, מלא באושר ותקווה למישהי טובה יותר בשבילנו. זו היתה תקופה נפלאה, אבא היה מאושר שוב, ולי היתה פתאום אחות גדולה. כזו שתמיד שומרת עלי ושאפשר לקחת לה את החולצות. כשהתבגרנו, קצת התרחקנו. נדמה לי שזה התחיל בגיל 15, כשיובל הכירה לי את אופיר, החבר הראשון שלה. לא הצלחתי להבין למה היא צריכה חבר. הרי יש לנו אחת את השניה. במבט לאחור, ברור לי שהקנאה תמיד שכנה שם, בשקט. מוכנה לפרוץ החוצה. אמא של יובל היתה גם אמא שלי. לפעמים פחות, לפעמים יותר אבל תמיד ידעתי שעדיף משהו מאשר שום דבר."},{"t":"p","x":"ואז אבא עזב."},{"t":"p","x":"בטריקת דלת כזו שהדהדה את הקירות של הבית במשך שבוע. נשארנו ארבעתנו. אמא, יובל, אופיר ואני. פעם ראשונה בחמש עשרה שנה שהייתי לא רק בלי אמא, אלא גם בלי אבא. נקודה כזו בחיים, שמשנה את מסלולם. ומשנה אותך. לתמיד."}]},
  {"id":"mahapecha-1","t":"מהפכה","s":"חלק 1","p":24,"kind":"סיפור · חלק 1","blocks":[{"t":"p","x":"יום שבת, 20:15. היא הדליקה סיגריה בסיגריה. יושבת לה על המדרכה מול הבית, מקשיבה לצעקות של אמא ואבא. שוב ההתמודדות מקשה על הנשימה. מזיזה את הנשמה. חתולת הרחוב השחורה מתחככת ברגל היחפה. מנסה להוציא ממנה קצת חמלה אבל הנפש ריקה."},{"t":"p","x":"הכל היה בסדר עד הסגר השני. משפחה רגילה כזו. גרים בשכירות, קומה רביעית. מעלית. שלושה חדרים. אבא, אמא והיא. ילדה יחידה. חברות, חברים. בלי חניה."},{"t":"p","x":"סגר. אבא בבית. קם בצהריים והולך לישון אחרי ארוחת הבוקר. היא שומעת אותו מסתובב בלילה יחף על רצפת הפרקט. צועד הלוך וחזור במשך שעות. אחרי השבוע הראשון, הוא הפסיק לדבר עם אמא והתחיל לדבר לעצמו. רק הצעקות שלה מהדהדות בין קירות הבית והוא שותק. שותק והולך."},{"t":"p","x":"ילדה בת 14. גונבת סיגריה ראשונה מאבא.","c":"solo"},{"t":"p","x":"אף פעם היא לא ראתה את אבא עם זקן. ההפסקה של ההורמונים וטיפולי ההפריה לא תרמו ליציבות הבית. שנים שהם מנסים שוב. היא לא רצתה אח, או אחות. היה לה טוב לבד. החצי השני שלה שמת בגיל שלושה חודשים, תמיד היה איתה. וזה הספיק. ילדה טובה, שקטה, לומדת מזום לזום כל היום. מתחברת כדי להתנתק. מנסה להזכר בפרפרים שהרגישה לפני כמה חודשים, כשעומר מהכיתה המקבילה אמר לה בוקר טוב. תחושה חדשה כזו, ראשונית, שהיא לא מכירה. רגש בסגר."},{"t":"p","x":"צפוף לה. הראש קצת לא בסדר.","c":"line"},{"t":"p","x":"משהו מרגיש בפנים אחרת.","c":"line"},{"t":"p","x":"היא רואה את אמא בוכה ומרזה.","c":"line"},{"t":"p","x":"ואבא שותק.","c":"line"},{"t":"p","x":"בשבוע האחרון כבר לא שומעים בבוקר את התריסים נפתחים. הבית חשוך. הטלפון מהחברות כבר לא מצלצל, כמות ההודעות בקבוצות הוואטסאפ יורדת, אין חוויות חדשות, אין רכילות, אין. מישהי עם מסכה לבנה ודגל ורוד ענק עוברת מולה על הכביש. היא מרימה את הראש. \"לאן?\" שאלה. \"לכיכר\", ענתה הורודה, \"אנחנו המהפכה\"."}]},
  {"id":"mahapecha-2","t":"מהפכה","s":"חלק 2","p":26,"kind":"סיפור · חלק 2","blocks":[{"t":"p","x":"חיפשתי אותה בין כל האנשים. העיניים סורקות בקצב מהיר פרצוף פרצוף. לאן היא הלכה? לפני רגע ראיתי אותה מהמרפסת יושבת על המדרכה. כן, אני יודע שהיא מעשנת כבר חודש, אבל אין לי אנרגיות להתמודד גם עם זה. פאק איט, גם אני מעשן מגיל 16. עדיין לא מתתי מזה. יצאתי מהבית בריצה למעלית. עדיין יחף ובבוקסר שלא החלפתי יומיים. לקח למעלית מלא זמן להגיע, אז ירדתי במדרגות, מדלג למטה על כל מדרגה שניה. לא העליתי דופק כבר חודש וממש הייתי צריך להסדיר את הנשימה. איזו סטירה. לחשוב שלפני שלושה חודשים הייתי רץ עשרה קילומטר כל שבוע."},{"t":"p","x":"תמרה! צעקתי. ת מ ר ה! הרחוב היה שקט כמו ביום כיפור. ברקע שמעו את הצפצפות והמגפונים מכיוון כיכר הבימה. הנחתי שנסחפה לשם. התקשרתי לטלפון שלה. נעמה ענתה לי. בוכה. היא השאירה את הטלפון בבית. ביקשתי מנעמה לזרוק לי מכנסים, חולצה וכפכפים מהמרפסת לרחוב."},{"t":"p","x":"כל דקה משמעותית. כמובן שהיא זרקה אלי את החולצה שאני שונא. התלבשתי בזריזות באמצע הרחוב ורציתי לכיכר. ובכיכר, א.נשים נלחמים. א.נשים עם ניצוץ בעיניים, א.נשים בוורוד, בשחור ובכל צבעי הקשת."},{"t":"p","x":"עצרתי לנשום את התקווה.","c":"solo"},{"t":"p","x":"נשימה עמוקה כזו, שאתה מרגיש מקצות האצבעות ועד הקצוות המפוצלים של השיער. בתוך כל הרעש, מצאתי שקט. לראשונה בהרבה מאוד זמן. התקשרתי לנעמה. היא עדיין בוכה."},{"t":"p","x":"\"בואי. תתלבשי ובואי\"."},{"t":"p","x":"\"מצאת את תמרה? הכל בסדר?!\" היא התנשמה בכבדות מהצד השני."},{"t":"p","x":"\"עדיין לא. אבל הכל יהיה בסדר אם תגיעי לכיכר\"."},{"t":"p","x":"\"להבימה?\""},{"t":"p","x":"\"כן. יש כאן תקווה, ותמרה היא חלק ממנה\"."},{"t":"p","x":"נעמה הגיעה אחרי עשר דקות. נעמדה לידי עם עיניים אדומות."},{"t":"p","x":"\"איפה תמרה?\" היא שאלה."},{"t":"p","x":"\"תמרה? הצטרפה להפגנה, בשביל כולנו\" עניתי והחזקתי לה את היד."},{"t":"p","x":"עמדנו על המדרכה בצד.","c":"line"},{"t":"p","x":"צמוד למחסומים של המשטרה.","c":"line"},{"t":"p","x":"לרגע היינו מאוהבים שוב.","c":"line"}]},
  {"id":"arbaim-ushtaim","t":"ארבעים ושתים","s":"","p":28,"kind":"שיר","blocks":[{"t":"st","l":["עמדתי מרחוק וצפיתי בלהבות הענק מחריבות את מפעל חיי.","השמים בהקו בצבעי לבן ושחור ואדום.","העיניים שלי הצטמצמו לכדי חריץ צר, מנסה למנוע מהעשן לצרוב לי את הנשמה.","לנתק את חוט השדרה של הנשימה."]},{"t":"st","l":["עשרות ציורים, רעיונות ואהבה אחת נעלמו ברגע.","צבעים חזקים מתפוררים לאפר שחור.","גיהנום.","לצפות בתקופת חיים מתאדה בטמפרטורה גבוהה.","חיתוך חבל הטבור.","פרידה במקום חיבור."]},{"t":"st","l":["ארבעים ושתיים זה גיל שעדיין אפשר להתחיל מחדש?","להתחיל לייצר, ליצור ולשחזר?","למצוא את הכוחות לבנות בית חדש?","ואהבה?"]},{"t":"st","l":["לאורך חיי אגרתי חוויות, אצרתי רגעים.","הוצאתי אותם החוצה בפרצים גדולים.","הבשלתי לאורך השנים.","על אש קטנה, גחלים לוחשות.","גיצים שעפו בשמי חיי החשוכים,","נתפסו על הבד במריחה. לכלוכים."]},{"t":"st","l":["תכננתי כל פרט בשנה האחרונה.","אילו יצירות אמכור ומה ישאר בשבילי.","מה אפרסם בתהליך ומה אנצור בליבי.","מתי אזעיק את מכבי האש והמשטרה","והיכן אחביא את מפתח חדר המיתות, כשהיא ישנה."]}]},
  {"id":"yuval-0","t":"אני אצל יובל","s":"פרק 0","p":30,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"חיינו התנהלו ברביעיה. מירב, שכבר לא קראתי לה אמא יותר, יובל ואופיר, ואני – שנקלעתי למציאות ההזויה הזו. במשך שבע שנים ניסיתי לרדוף אחרי אבא, להבין מה קרה. בגרויות בלי אמא ואבא. צבא, טיול של אחרי. יובל, אחותי הגדולה, תמיד הייתה שם בשבילי וגם בשביל אופיר. ואחרי הטיול של אחרי.. קצת הלכתי לאיבוד. ניסיתי לחזור להיות עם יובל, אבל היא ואופיר היו אחד. אז ניגנתי המון, ושרתי מעט. ביליתי שעות על הספסל מול הגלים וניסיתי להבין לאן ואיך. יום אחד, ממש לפני השקיעה, כשרוח חמה של קיץ עושה לי נעים בחצי הראש המגולח הבנתי מה אני ויובל צריכות לעשות. איך נחזיר את הכל חזרה."},{"t":"p","x":"רצתי הביתה, שוכחת את הכפכפים שלי מכוסים בחול מתחת לספסל."}]},
  {"id":"yuval-1b","t":"אני אצל יובל","s":"פרק 1 (שוב)","p":31,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"אני שולחת! נבחתי על יובל. אני לא יכולה כבר להחזיק את זה בבטן. הידיים שלי רעדו, הבנתי היטב מה יקרה אם אשלח את התמונה הזו. אבל הראש שלי התפוצץ. תמיד הייתי הרגועה בין שתינו. \"אלמה האדישה\", יובל היתה קוראת לי. והנה כאן, אני בסערת רגשות שלא חוויתי מעולם. השנה האחרונה עוברת לי שוב בהילוך מהיר."},{"t":"p","x":"\"חכי! אל תשלחי!\" יובל צעקה אלי מהצד השני של החדר. \"שלחתי\", גמגמתי. מנסה עוד להבין איך הגענו אתמול למצב שיובל שוב מורידה לי סטירה. יובל קפצה מעל המיטה, חוטפת לי את הטלפון מהיד. \"את מבינה מה עשית?! זהו, זה נגמר!\" היא צעקה עלי, ומיד התחלתי לבכות. פעם יכולתי להכיל את התקפי הזעם שלה. זה לא היה קשה מדי, כי אופיר ספג את כל האש. אבל אופיר איננו."},{"t":"p","x":"בכיתי בשקט, אף פעם לא ידעתי לבכות בקול. מלא דמעות שיורדות לי מהחיים ומטפטפות לתוך החולצה."}]},
  {"id":"yuval-2b","t":"אני אצל יובל","s":"פרק 2 (שוב)","p":32,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"הטלפון רטט אצל יובל ביד. לא ראיתי מי זה. \"תני לי את הטלפון\" ביקשתי. היא ניתקה בהפגנתיות והשקט התפזר בחזרה בחדר. שוב טלפון, לא יכולתי להאמין שאבא באמת מתקשר."},{"t":"st","l":["\"אבא, בוא לקחת אותי, אני אצל יובל\""]},{"t":"p","x":"לא הצלחתי להבין למה הוא צועק עלי."}]},
  {"id":"kesher-zugi","t":"קשר זוגי","s":"","p":33,"kind":"שיר","blocks":[{"t":"st","l":["קשרתי את נעמי חזק.","ממש חזק.","\"אתה מכאיב לי\", היא צעקה","ואני הסתובבתי","לא שמעתי","לא חשבתי","יצאתי וטרקתי את הדלת של הבית."]},{"t":"st","l":["פס הזיעה הכתים את החולצה","החלפתי באוטו למכופתרת שהיתה תלויה על משענת הראש.","קצת בושם ודאודורנט ואני כמו חדש.","הנשימה מאיטה לקצב הרגיל."]},{"t":"st","l":["קניתי פרחים בדרך חזרה וגם איזה בקבוק יין.","היא לא תשכח את הערב הזה חשבתי לעצמי בעודי חונה בכחול לבן צמוד לבית."]},{"t":"st","l":["פתחתי את הדלת עם המרפק.","\"היי ממי\" צעקתי מהכניסה, \"איך עבר עלייך היום?\"","נעמי ישבה על הכסא במטבח, הראש היה קצת שמוט קדימה.","\"למה את לא עונה לי?\" התחלתי להתעצבן.","היא ישבה שם, מביטה בי ושותקת."]},{"t":"st","l":["השוטר קפץ עלי מאחורה.","\"אתה מכאיב לי!\" צעקתי.","נעמי הסתובבה.","היא שמעה.","היא חשבה.","וטרקה את הדלת אחרי."]}]},
  {"id":"metzta-er","t":"מצטער","s":"","p":35,"kind":"שיר","blocks":[{"t":"st","l":["יש לי חברים,","לוחמים.","שידעו להמריא אבל מעולם לא נחתו."]},{"t":"st","l":["היו לי אחים,","יותר מידי כאלו.","היום אני מרגיש כמו בן יחיד."]},{"t":"st","l":["הפסקתי ללכת לבתי קברות מזמן,","כי לא ידעתי במי לבחור.","איך אפשר?"]},{"t":"st","l":["אני נושא את כולם איתי,","כל השנה.","היום זה היום שאני קובר אותם בחזרה."]}]},
  {"id":"yuval-3","t":"אני אצל יובל","s":"פרק 3","p":36,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"אני זוכר שיובל נכנסה עם מירב הביתה. אני זוכר את החיבוק שנתתי לה ואת המבטים של יובל ואלמה אחת אל השניה. כמה דיברנו על הרגע הזה, שנצטרך להפוך אותן לאחיות. מירב היתה הרוח שלי, מי שהרימה אותי מתוך הבור העמוק שהייתי בו במשך כמה שנים טובות. היא הצליחה להבין שאחרי הפרידה שלי מדניאל, נשארו בי זרעים שניתן יהיה לגדל מחדש. ארבע שנים של לגדל את אלמה לבד גבו ממני מחיר נפשי כבד. לא התגעגעתי לדניאל, אבל לא יכולתי לסלוח לה על איך שברחה עם הבן שלנו. התגעגעתי אליו נורא. לא הצלחתי לגדל את אלמה כמו שרציתי, כל תזוזה, כל חיבוק, דמיינתי אותו במקומה."},{"t":"p","x":"יובל ואלמה הפכו לאחיות, חברות. גדלו ביחד, החליפו בגדים וחלקו חוויות של התבגרות. עד היום הזה שאופיר נכנס בדלת. ישבנו לארוחת ערב, אני, יובל ואופיר. אלמה ניגנה במרפסת למעלה. שאלתי אותו מהיכן הוא, מה הוא לומד ואיך קוראים להורים שלו. \"ההורים שלי גרושים, אני חי עם אמא שלי. דניאל\"."},{"t":"p","x":"נחנקתי."}]},
  {"id":"yuval-31","t":"אני אצל יובל","s":"פרק 3.1","p":37,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"חמש עשרה שנה, והנה הוא יושב כאן מולי ואלמה לא יודעת שיש לה אח. \"תסלחו לי\". קמתי מהשולחן והלכתי לחדר שינה אל מירב. רבנו באותו ערב כמו שלא רבנו מעולם. לא ידעתי איך להתמודד עם זה שהסתרתי מאלמה שיש לה אח. הבנתי שאני יכול לפרק כאן שתי משפחות, אז עשיתי מה שאני יודע הכי טוב. טרקתי את הדלת. החלטתי להפגש עם דניאל."}]},
  {"id":"yuval-4","t":"אני אצל יובל","s":"פרק 4 ואחרון","p":37,"kind":"סיפור בפרקים","blocks":[{"t":"p","x":"במקום לפגוש את דניאל, פגשתי שוב את הבור העמוק שלי. שוכב לי באיזה דירה מעופשת בדרום העיר. בקבוקים ריקים וסיגריות ממלאים לי את המיטה. בוחר להתעלם מהטלפונים של אלמה ומפחד לצאת חזרה לעולם האמיתי. קורא כל הודעה שהיא שולחת, אבל לא מגיב לעולם. אחרי שנתיים, ההודעות והטלפונים נעשו נדירים יותר. היא ידעה שאני קורא את ההודעות, הפידבק היחיד ממני היו שני ✓✓ הכחולים ליד ההודעה שלה. האמנתי שהם מסמנים לה שאני חי."},{"t":"p","x":"כשאתה בבור כזה עמוק, שקוע בתוך החושך, מאוד קשה לצאת החוצה. כל קרן אור מסנוורת בכאב, הראש מרגיש בנוח רק כשאתה שוכב ועוצם עיניים. דיפרסיה."},{"t":"p","x":"צלצול של הודעה. תמונה מאלמה. הסתובבתי הצידה ופתחתי את הטלפון. התמונה של אופיר, שוכב על הרצפה של השירותים כשעשרות קופסאות ריקות של כדורים מפוזרות סביבו הסירה לי את כל ההגנות ברגע."},{"t":"p","x":"התקשרתי לאלמה."}]},
  {"id":"ahavat-emet","t":"אהבת אמת","s":"","p":39,"kind":"שיר","blocks":[{"t":"st","l":["הצעתי לאישתי נישואין,","בפעם השניה.","היא קיבלה עוד יהלום","לענוד על אצבעה."]},{"t":"st","l":["ירדתי על הברך","הילדה מחאה כפיים.","היא אמרה שוב \"כן\"","והתנשקנו פעמיים."]},{"t":"st","l":["היה ערב נהדר,","אמבטיה מלאה בקצף.","זרם הרבה יין","ונטפליקס ברצף."]},{"t":"gap"},{"t":"st","l":["הוא הציע לי נישואין","בפעם השניה.","הביא לי עוד טבעת","לא ממש יפה."]},{"t":"st","l":["כרע הוא על ברכיו","הילדה היתה שמחה.","אמרתי לו \"ברור\"","וזייפתי נשיקה."]},{"t":"st","l":["קיוויתי שהאמבטיה תעזור","אך בסוף לקחתי אקמול.","שתיתי כדי לשכוח","את המכות של אתמול."]}]},
  {"id":"makshiva","t":"מקשיבה אבל לא שומעת","s":"","p":41,"kind":"סיפור קצר","blocks":[{"t":"p","x":"\"ארבעה ימים לא ישנתי\" הוא אמר לי. \"ארבעה ימים\"."},{"t":"p","x":"ואני מקשיבה אבל לא שומעת."},{"t":"p","x":"למדתי להדחיק, להתעלם, לבלוע את הסערה שמתחוללת בתוכי. לא נותנת לחרדה אפילו חריץ קטן לברוח. מחזיקה את החושך הזה בחדר קטן קטן בפינה השמאלית התחתונה של בית החזה והחושך הזה לוחץ."},{"t":"p","x":"הוא לא נראה עייף, רק קצת מלוכלך ועם זיפים ארוכים יותר. הוא אפילו לא מציץ לחדר של הילדים לראות אותם ישנים. זה הזמן האפור שלו. השעה הזו בין החיים שבחוץ לחיים שבבית."},{"t":"p","x":"אני תוהה לעצמי איפה הוא מחזיק את הכל. איך הוא מכיל את כל החיים שבחוץ בפנים. לא נותן להם להרעיד את הבית."},{"t":"p","x":"\"עוד לא נתתי לכלבים לאכול\" ממלמלת אליו. הוא אוסף את שאריות ארוחת הערב וזורק את השקית אל הפח בחוץ. בטח צריך עוד נשימה של אוויר נקי. מאכיל את הכלבים ונכנס למקלחת."},{"t":"p","x":"מנסה להירדם על צד שמאל עם הכרית בין הידיים. עושה את עצמי ישנה, נושמת עמוק ובשקט. יד כבדה עוטפת את בית החזה שלי."},{"t":"p","x":"הוא שוב חזר קצת אחר, מפלחת אותי ההבנה. לפחות הוא חזר."}]},
  {"id":"hapaam-harishona","t":"הפעם הראשונה","s":"","p":43,"kind":"סיפור","blocks":[{"t":"p","x":"\"היא הלכה לישון מזמן\" ענתה לי אמא שלה כשהתקשרתי. \"אני אמסור לה שחיפשת אותה\"."},{"t":"p","x":"\"תגידי לה שאני ממש מצטער\" רציתי להגיד אבל לא היה לי אומץ. במקום זה יצא לי \"טוב\" עייף כזה וחסר משמעות. ניתקתי את הטלפון. הסתובבתי לצד השני, מעורער קצת."},{"t":"p","x":"כל כך הרבה פעמים הייתי ככה בצד השני ואף פעם לא חשבתי על זה. תמיד הנחתי שהיא תהיה שם כשאחזור חזרה. \"תסתובב\" היא אמרה, \"אני אחבק אותך\". והצד השני שלי היה מתחבק איתה צמוד צמוד. כל לילה בעשר השנים האחרונות."},{"t":"p","x":"התיישבתי על המיטה והכנסתי את הרגליים שעוד היו רטובות מהמקלחת לנעלי הבית. יצאתי למרפסת והדלקתי סיגריה. שתי כוסות היין שמזגנו לפני ארבע שעות עוד עמדו שם חצי מלאות על המעקה כמו נרות זיכרון. לקחתי את הכוס שלה והצמדתי את הזכוכית הקרה לשפתיים שלי. ממש קיוויתי שיהיה לה עוד את הטעם שלה. מגלגל לעצמי את השיחה שוב ושוב בראש. מנסה להבין איך הגעתי למצב הזה שהיא צועקת עלי ואני צועק עליה חזרה. תמיד בויכוחים שלנו אהבתי לשתוק. ידעתי שהיא צודקת, אבל הכעס שבשתיקה תמיד מכאיב לי יותר. הוא נעצר בתוכי ואני לא נותן לו לברוח. הוא כואב נורא אז אני מחזיק אותו עוד קצת. מזיז אותו מהבטן ללב, ואז קצת לריאות, שהשאיפה תהיה יותר כבדה. לוקח לכאב הזה כמה ימים להתמוסס לתוך מחזור הדם, להתאייד עם הזיעה שלי החוצה."},{"t":"p","x":"אז אני חוזר להיות בן אדם."},{"t":"p","x":"אבל היום, בפעם הראשונה, צעקתי בחזרה.","c":"line"},{"t":"p","x":"והיא שתקה. והמשכתי לצעוק. והיא שתקה."},{"t":"p","x":"השקט הזה, שכל כך אהבתי לשנוא, נעלם. עכשיו הראש שלי מלא ברעש שאני לא מצליח להוציא. הוא ממלא אותי ברגש שלא הכרתי. כאב כזה. שקשה להסביר, אבל יודעים שהוא שם. הטלפון מצלצל בחדר. רצתי פנימה. זה היה אח שלי. שוב לא עניתי לו כי ידעתי שלא אצליח לשמוע אותו בתוך כל הרעש הזה. גוללתי את ההודעות האחרונות ביני לבינה. חיפשתי איזה רמז קטן בין כל הלבבות והפרחים שהיה יכול לעזור לי לראות את זה מגיע. העולם התהפך לי והראייה מטשטשת. \"אני לא חוזרת אליך\" קפצה הודעה."},{"t":"p","x":"לא עניתי."},{"t":"p","x":"צלצול טלפון מהמספר שלה העיר אותי בבוקר. \"יעלי?\" מלמלתי."},{"t":"p","x":"\"היא כבר לא איתנו\" ענתה לי אמא שלה בשקט, \"הילדים נשארים כאן\"."},{"t":"p","x":"שמעתי את סירנות המשטרה מלמטה."}]},
  {"id":"holechet","t":"הולכת","s":"","p":46,"kind":"שיר","blocks":[{"t":"st","l":["כמה קשה לגרום לה לחזור","מהצד השני של","המזרון."]}]},
  {"id":"tzaad-tzaad","t":"צעד צעד","s":"","p":47,"kind":"סיפור","blocks":[{"t":"p","x":"התיישבתי עם הפנים אל הקיר. ממרחק כזה, הבטון החשוף היה נראה כמו גלים של ים, הוא צעק עלי ולא עצר, אפילו לא בשביל לקחת נשימה קטנה בין לבין. פתאום נגמר לו האוויר ונהיה שקט לרגע קצר. הרגשתי את הרוח זורמת לי בתוך הוורידים. הרגשתי את המבטים של כולם שורפים לי את הגב."},{"t":"p","x":"מהרגע שנכנסתי לכיתה לא אהבתי את השיעורים שלו ומהרגע הראשון היתה לי הרגשה שהוא לא אוהב אותי. הייתי מאחרת בקביעות, לא מכינה שיעורים אבל דואגת להוציא ציונים טובים במבחנים כי ידעתי שזה יוציא אותו מדעתו. הוא מצידו דאג תמיד לוודא שאני ארגיש רע והיה מנסה להכשיל אותי בכל התרגילים. יחסים זה הדדי ודאגנו לתחזק אותם ככה."},{"t":"p","x":"הוא המשיך לצעוק אבל כבר לא שמעתי. הסתכלתי על הקצף של הגלים ודמיינתי את עצמי צוללת פנימה, לשקט שמתחת למים. למלח של הים שמתערבב לי על השפתיים. יד קטנה נגעה לי בכתף, הוצאתי את הראש וניגבתי את הפנים. \"בואי\" היא לחשה לי. \"אמא מחכה לך עם ההינומה\"."},{"t":"p","x":"שישה חודשים של הכנות, שמונה שנים של זוגיות, חברות, הדדיות והנה אני, עומדת מול המראה עם עיניים נפוחות. עמית היה המרצה שלי באוניברסיטה. עמית היה הסיוט שלי באוניברסיטה. עמית היה הפחד שלי. הסיבה שלא רציתי לבוא ללימודים בבוקר. עמית היה הזעם. ואני אהבתי אותו ביחס הפוך לשיעורים שהוא לימד. אמא חיזקה לי את ההינומה עם הסיכות, ואני רק רציתי להניח את הראש על הכתף להתכרבל עמוק עמוק ולא לצאת משם עד הבוקר. עמית חיכה לי בחוץ, כולו זורח מאושר כאילו בדיוק סימן לי נכשל על עבודת הגשה. שמעתי את הצלילים המוכרים מנגנים ברקע, החזקתי לו את היד חזק חזק, וצעדנו."},{"t":"st","l":["כל צעד והמחשבה כבדה עלי.","כל צעד והראייה סוגרת.","כל צעד ואני לא שומעת."]},{"t":"p","x":"האורות סינוורו אותי כשהסתובבנו על הבמה לכיוון האורחים. אמא לחשה לי מהצד, \"זה בסדר, את מהממת\". דפיקות הלב שלי היו כל כך חזקות. סרקתי את האורחים, חיפשתי את הפנים המוכרות כדי להאחז בהן. הכל היה מטושטש, מלבד הפנים הכועסות של אבא שנשען על קיר הבטון."}]},
  {"id":"mashber","t":"משבר","s":"","p":49,"kind":"שיר","blocks":[{"t":"cols","a":["יש לי משרד","מול הים והנוף","מכונה שטוחנת פולים","לאספרסו ארוך","וג'יפ חדש","בחניון מחכה","אוזניות לבנות","ושיניים צחורות","","יש לי אישה","וארבעה ילדים","וחדר כושר","ובריכה","עם מים חמים","וכרטיסי טיסה ליפן","ואחד גם לסין","ומחלקת עסקים","לכל החברים","","",""],"b":["","","","אבל אני עדיין הילד","שלא הסתדר בכיתה","ונכשל במבחנים","ורב עם מורים","שברח לגלים","מבלי לספר","וישן על ספסל","במקום אצל חבר","","ורק כשהבנתי","בגיל ארבעים","שמרגישים שלמים","רק כשמגשימים","את הרצונות האמיתיים","מבלי לשים זין","על אם יפתחו עין","ועל מה יגידו","ומה יחשבו"]},{"t":"st","l":["אז עשיתי את מה שבאמת","רציתי","ולמדתי לשיר","לנגן","ולאהוב","והרגשתי מוכשר","ושלם","ומאושר."]}]},
  {"id":"atzmaut","t":"עצמאות","s":"","p":51,"kind":"שיר","blocks":[{"t":"st","l":["לפעמים,","כשכולם מרכינים את הראש בצפירה,","אני עומד על רגל אחת.","מתנדנד בין אוויר לנשימה.","נותן לרוח לנשוב לי בין האצבעות לאחיזה."]},{"t":"st","l":["לפעמים,","כשכולם מרימים את הראש לתקווה,","אני מוריד את הרגל השניה"]},{"t":"st","l":["וטומן אותך שוב עמוק באדמה."]}]},
  {"id":"apocalypse","t":"אפוקליפסה אתמול","s":"","p":52,"kind":"סיפור בשלושה פרקים","blocks":[{"t":"h","x":"המגפה"},{"t":"p","x":"היא מתה.","c":"solo"},{"t":"p","x":"מוטלת על רצפת ברזל מחורצת. קפואה. אני מרחף בשקט מעליה, מסרב להאמין שככה זה נגמר אחרי שלושת החודשים האחרונים. אני חייב לחזור הביתה חשבתי. העברתי מעט משקל ימינה, ומצאתי את עצמי חולף מעל המחוז המזרחי בגובה נמוך מבלי לחשוש לרגע מההשלכות. השקט המוזר התחלף בבהלה. איך ממשיכים מכאן את המאבק?"},{"t":"p","x":"נעמי אף פעם לא היתה חזקה מדי או אמיצה מדי, אבל היכולת שלה להתחבר לרשת היתה פנומנאלית. כמות הנתונים שהיא ספגה בשניה תמיד הרשימה אותי. אני לדוגמא, פחדתי להתחבר. פעם ניסיתי עם כמה חברים לקחת טריפ דיגיטלי כזה, אבל השיטור עלה עלינו תוך חמש שניות ומחק לנו את הזיכרון. מזל שלא פתחו לנו תיק."},{"t":"p","x":"נעמי הוציאה את האוזניות והודיעה לי שהיא מצאה אותה. לא האמנתי לה. יצאנו לשבת בחוץ, סופרים לאחור עד ראש השנה של 2035, מחכים להשבתה השנתית של המפעלים כדי שנהנה משבוע של שמש במקום העשן התמידי שהגיע מהמחוז הצפוני וכיסה את השמיים. אלו ימים קשים. לא יכולנו לדמיין את המצב הזה לפני חמש עשרה שנה. אבל הכל השתנה כל כך מהר אחרי המגפה הגדולה של 2020."},{"t":"p","x":"נעמי הייתה אז רק בת 14, ואני בדיוק חגגתי 45. היינו ספונים בבית, יוצאים עם מסכות בשביל לזרוק את הזבל. לא אשכח את הריח של השריפות, כשהתחילו להגיד לנו להיפטר מהגופות לבד כי אסור היה לקיים הלוויות. אלו היו כמה חודשים מאתגרים עד שהצליחו להשתלט על הנגיף, אבל הקושי האמיתי התחיל אחר כך. הכבישים שסגרו כדי להפריד בין המחוזות השונים ולמנוע הדבקה, לא נפתחו מעולם."},{"t":"p","x":"אמא של נעמי, אז עדיין אשתי, היתה מוגדרת \"עובדת חיונית\". היא היתה רופאת ילדים ונקראה לעבוד בבית חולים בצפון. אני זוכר את הערב שהכריזו על \"בידוד הפוך\" לאנשי הרפואה. אסור היה להם לחזור לבתים כדי למנוע הדבקה ולהשאיר מספיק מהם בחיים. כשבנו את חומות ההפרדה בין המחוזות, עוד הייתה לנו תקווה שנפגוש אותה כשהכל יגמר. הארץ התחלקה לחמישה מחוזות שונים. מחוז הצפון, מרכז, דרום ומזרח. ירושלים קיבלה מחוז משלה. הניסיון שהיה למדינה ממה שהתחולל בעזה, הביא לכך שהמדינה הצליחה לבצע את פרויקט החומות תוך שנתיים. מבצע \"תקווה\" קראו לזה. בארצות הברית לדוגמה, סיימו את הפרדת המדינות רק אחרי שבע שנים."},{"t":"p","x":"כמה קשה היה ערב הגירושים מרצון שלנו, כאשר הבנו שהחומות כאן כדי להישאר. נעמי לא השלימה עם המצב הזה מעולם. \"אני אגיע אליה!\" צעקה כשגיליתי לה שהתגרשנו. זה היה לילה של בכי ובריחה דיגיטלית מלאה ל-48 שעות ברצף."},{"t":"p","x":"אף אחד לא הבין מה החומות האלו יעשו להנהגה של המדינה. ביום שסיימו את הבניה והכריזו שבידוד הבית נפתח ועבר לרמת המחוז, חמשת המחוזות הכריזו על עצמאות. אף אחד לא חגג ברחובות. הריחוק החברתי לא גרם רק להפרדה בין האנשים, הוא גרם גם להתפתחות טכנולוגית מואצת. עבודה מרחוק, הייתה כורח המציאות, וההבנה שתקשורת מתבצעת רק בצורה דיגיטלית, גרמו לחברות המציאות המדומה לפרוח. נעמי התבגרה אל תוך אותה מציאות דיגיטלית מהירה. היא והחברים שלה ברחו אל תוך העולם הזה: שיעורים, דרינקים ואהבה."},{"t":"p","x":"הכל השתנה בתקופה ההיא, עצמאות המחוזות גרמה לי לנטוש את ההייטק ולהפוך להיות חקלאי. הצורך בייצור מזון תוך-מחוזי בגלל הבידוד המוחלט היה הזדמנות מעולה לבסס את עצמך כעובד חיוני למקרה חירום. כמו כן, היתה הזדמנות כלכלית לא קטנה לצידה."},{"t":"p","x":"היחסים ביני לבין נעמי ידעו עליות וירידות, כנראה כמו כל גיל התבגרות טיפוסי של אבא ובת שגדלה ללא אמא. הצלחנו לבסס תא משפחתי חזק, אבל תמיד קינן בי החשש שהיא תחליט לחפש אותה."},{"t":"p","x":"ככל שהעולם היה מחובר – הוא היה מנוכר. העולם כמו שהכרנו אותו, שכלל שמות אמיתיים, סלפי ותמונות בלי סוף, נעלם. במקומו הופיעו (או יותר נכון חזרו) הכינויים, האווטרים והאנונימיות הרשתית המלאה. ממש תיקון של העולם הדיגיטלי לאיבוד הפרטיות בעולם האמיתי. הכל השתנה מהר מאוד. חוק מור, שצפה הכפלה בכוח החישוב כל שנתיים, כבר לא תפס. החברות הצליחו להכפיל את כוח החישוב כל שישה חודשים, ואת קצב העברת המידע על רשת האינטרנט כל שנה. אפל הכריזו על אוזניות הדאטה החדשות. Immersive Reality הם קראו לזה."},{"t":"p","x":"ואני.","c":"solo"},{"t":"p","x":"אני עשיתי את הטעות הגדולה בחיי וקניתי אותם לנעמי."},{"t":"h","x":"לחיות בלי לישון"},{"t":"p","x":"אני לא אשכח את הפעם הראשונה שנעמי התחברה. אפל, כמו אפל, הפכו את תהליך ההתמזגות לפשוט יחסית. נעמי נשכבה על המיטה, טפטפתי לה שתי טיפות נוזל ראיה לכל עין והיא חיברה את האוזניות לאייפון Z שלה. \"Siri, please immerse me\" היא מלמלה."},{"t":"p","x":"נהיה שקט. היא שכבה שם על המיטה עם עיניים פקוחות במשך שעתיים מבלי לזוז או להגיב. שעתיים שישבתי לידה מבלי לזוז. לראשונה מתמלא דאגה אמיתית. האוזניות הקרינו גלי גמא רחבים של מידע שגורמים לך לראות, לשמוע ולהרגיש הכל. חיישן קריאת הנוירונים, שפותח לראשונה כדי לגבות אנשים, היה קורא ומפענח את הפקודות של המוח בלי הצורך לדבר או להזיז את הגוף שלך באמת. היה מספיק לחשוב מה אתה רוצה להגיד או מה אתה רוצה לעשות. אחרי שעתיים, נעמי התנתקה. \"אבא. זה מטורף. ממש הייתי שם. זה כמו עולם חדש!\" ואכן, לא רק עולם חדש נגלה אלינו, החיים שלנו התחילו מחדש בשלישית."},{"t":"p","x":"חוץ מניסיון ההתחברות הבודד שלי, לא התמזגתי יותר בחיים. המוח שלי לא עמד בדרישות המינימום הנדרשות, ולכן זמן ההתאוששות שלי היה בלתי נסבל. חייתי את העולם החדש דרך נעמי. תמיד עמדתי לידה, מרגיש שאני צריך להגן עליה מהעולם האמיתי בזמן שהיא נלחמה בשביל שנינו בעולם החדש. ישבנו שעות אחרי כל סשן וניתחנו לעומק מה קרה, מי נגד מי ואיך אנחנו יכולים לבסס את עצמנו גם בעולם המקביל. בעולם המקביל לא היו מחוזות, אפשר היה לטייל בעולם כרצוננו, לטוס מיבשת ליבשת וליצור קשרים עם אנשים חדשים. אפל, ששלטו בעולם הזה, דאגו שהיכולות האנושיות והטכנולוגיות בעולם המקביל יהיו שוות לעולם האמיתי. לא היו שם טילים למאדים (אילון מאסק פשט את הרגל אחרי שאי אפשר היה יותר לכרות ניקל לטובת בטריות למכוניות), ולא יכולת לעוף או לחיות בלי לישון. השינה היתה מסונכרנת לעולם האמיתי ע\"י השעון החכם."},{"t":"p","x":"נעמי גדלה להיות זרקונית בעולם החדש (מעמד שווה ערך למנהלת מפעל בעולם האמיתי), מה שאיפשר לנו להרוויח הרבה. המרת הכסף מוירטואלי לאמיתי, דרשה מס קטן לאפל ולכן נמנענו מזה ככל שיכולנו. ההבדלים בין איכות החיים של נעמי בעולם המקביל שבו היא היתה בעשירון העליון לבין אלה בעולם האמיתי, שהיו רחוקים מזה, גרמו לה להתמזג ליותר ויותר שעות. לא יכולתי לשמור עליה יותר. בהתחלה, עזבתי אותה לרגעים, ולאחר מכן כבר לשעות רבות. על הסיפורים שלה לא הייתי מוותר. המשכתי לחיות במקביל את העולם השני דרכה."},{"t":"p","x":"ואז היא סיפרה לי על המאבק.","c":"solo"},{"t":"h","x":"האל מתוך המכונה"},{"t":"p","x":"הרוח הכתה בקסדה שלי כל הדרך חזרה. הטיסה חזרה מערבה, עם הידיעה שנעמי כבר לא בחיים, חלחלה אלי לאט לאט. חשבתי שאני צריך להמשיך את דרכה. להמשיך את כל העשייה שלה בשלושת החודשים האחרונים. להמשיך להלחם, להמשיך את המאבק. הטיסה בעולם הוירטואלי הרגישה אמיתית לגמרי ולמרות שההתמזגות הזו היתה רק השניה שלי בחיים, התפלאתי איך עם כל החוויות המציאותיות האלו, אתה עדיין יודע ומבין שאתה במציאות מקבילה, שאתה ממוזג. הסתכלתי למטה, המחוז המזרחי במציאות האלטרנטיבית היה שונה לגמרי מהמחוז המזרחי במציאות, או ככה לפחות רציתי להאמין כי לא עברתי במחוז המזרחי מאז המגיפה."},{"t":"p","x":"רציתי להתנתק כבר, לחזור למציאות שלי, לחבק את נעמי ששוכבת לידי על המיטה ללא רוח חיים. להרים אותה לנהר ולהיפרד ממנה כראוי. ההתנתקות עצמה הייתה יכולה לקרות רק כאשר המיקום הוירטואלי והמציאותי היו זהים, כלומר היתה לי לפחות עוד חצי שעה של טיסה עד שאגיע למיטה שלי שאני שוכב בה כרגע. הרבה זמן לתכנון ומחשבות, הרבה זמן להיזכר בכל פרט ופרט שגילגל את נעמי מזרקונית לקיסרית. הרבה זמן לחשוב על איך נתתי לה לשקוע עמוק עמוק הרחק מהעולם האמיתי. האם הייתי אבא רע? האם היתה לי ברירה? ניסיתי להודות באמת, שחייתי דרך הסיפורים שלה, שקיוויתי שהמאבק יצליח ויגרום להפיכה גם בעולם האמיתי. אבל נעמי היתה קיסרית, ואני הייתי רק חקלאי."},{"t":"p","x":"מבעד לערפל, ראיתי את חומת ההפרדה של המחוזות מתקרבת אלי במהירות, בשבריר שניה החלטתי שמספיק. העברתי משקל קדימה לכיוון החומה וצללתי למטה באובדן שליטה מכוון. נעמי חיבקה אותי חזק על המיטה, האוזניות עדיין אצלי באוזניים."}]},
  {"id":"insomnia","t":"אינסומניה של אבל","s":"","p":60,"kind":"עמוד ריק","blocks":[]},
  {"id":"elegantit","t":"אלגנטית","s":"","p":61,"kind":"סיפור קצר","blocks":[{"t":"p","x":"תמיד דמיינתי את עצמי אלגנטית, מתלבשת מחויט לעבודה, נועלת עקבים גבוהים עם אודם אדום ותיק ג'יימס בונד כזה, מעור חום עם אבזמים גדולים. אלגנטיות היתה המילה שהכי אהבתי, הייתי מתאמנת על המשמעות שלה בלילות מול המראה. איך להיכנס לאוטו כמו ליידי, איך לצאת ממנו כמו כוכבת. איך לנגב את הפה עם טישו, להתעטש למרפק ואפילו סיגלתי לעצמי איזו קידה קטנה כזו, אלגנטית, כשאני אומרת להתראות. אמא תמיד הייתה צוחקת עלי. \"את רק בת 16, תשמרי את הגינונים האלו לאחר כך\", ואני צחקקתי עם פה סגור, מנצלת כל הזדמנות להתאמן."},{"t":"p","x":"קמתי עם הנגאובר נוראי אחרי אותו לילה. שטפתי את הפנים, סירקתי את השיער עם שביל בצד, תיקנתי את האודם. אלגנטי זה לא היה, הרהרתי בעודי מדביקה את הנפש שלי מחדש."},{"t":"p","x":"מקווה שאמא לא תצחק כשאספר לה."}]},
  {"id":"ladaat-lachzor","t":"לדעת לחזור","s":"","p":62,"kind":"סיפור","blocks":[{"t":"p","x":"הרגלים נגעו בגלים.","c":"solo"},{"t":"p","x":"החיים עצמם נזלו ממך טיפה אחרי שהשמש נעלמה מתחת לקו האופק."},{"t":"p","x":"החניה היתה כבר ריקה. סגרתי את הדלת, משאיר את הכפכפים והחולצה במושב לידי. רצתי הכי מהר שיכולתי, חולף על פני פנסים של טלפונים שמאירים את שביל העפר."},{"t":"p","x":"\"נ ע מ ה!\"","c":"solo"},{"t":"p","x":"הים חיבק את הצעקה שלי והטביע אותה למעמקים."},{"t":"p","x":"אף אחת לא ענתה."},{"t":"p","x":"הלכת אחרי הצהריים, היה נדמה לך שאת שוב לבד. הרגשת את הבוקר הזה מכביד על רגלייך. אז איך החיים שלך? על מי את חושבת?"},{"t":"p","x":"הדלקת סיגריה אחרי סיגריה. שואפת את האשמה, נושפת את הספק. לאן את הולכת מכאן?"},{"t":"p","x":"עמדתי בשקט סורק את החושך, המים והחול. להבה קטנה של מצית בקצה של החוף היתה הסימן שחיכיתי לו. פתחתי את הטלפון, קורא שוב את שרשור ההודעות שהגיע אחרי הצעקות. משחזר את הסיטואציה בראש."},{"t":"p","x":"שמעת אותי מגיע מאחוריך, הגוף שלך התכווץ. \"מה הוא עושה כאן?\" חשבת לעצמך."},{"t":"p","x":"הידיים שלי עטפו אותך."},{"t":"p","x":"חיבקתי אותך חזק חזק.","c":"line"},{"t":"p","x":"הנשימות שלנו הסתנכרנו לאט לאט.","c":"line"},{"t":"p","x":"הסתובבת אלי והתנשקנו.","c":"line"},{"t":"p","x":"שכחנו כבר כמה חשוב להתגעגע לפעמים."}]},
  {"id":"mishehi","t":"מישהי להיאחז בה","s":"","p":64,"kind":"סיפור","blocks":[{"t":"p","x":"קפצתי למים, כל הרעש שהיה לי בראש הפסיק בשניה. תמיד אהבתי את זמן השחייה שלי. השקט הזה גורם לך להתרכז בכל תנועה, המים עוטפים אותך מכל כיוון, תחושה עוברית. ראשונית. מנותקת. לא מצליח לנשום. הידיים זזות, הרגליים בועטות, הקיר מתקדם לעברי, אבל אני לא מצליח לנשום. מצוקה. הריאות שלי מתפוצצות והראות מתערפלת. אני מנסה להוציא את הראש מהמים אבל הוא נתקע במשהו שאני לא מצליח לראות. אני מחליט לעצור ולהוריד דופק."},{"t":"p","x":"שנים היה לי תחביב להוריד דופק. הייתי מחזיק במעקה של הבריכה ללא תזוזה, עוצר את הנשימה וצולל. מדמיין את הגלים של הים נשברים לפי קצב הלב שלי ואז מרגיע את הים ואיתו דפיקות הלב היו יורדות. מסונכרנות. הייתי עוצר את הנשימה לארבע דקות וחצי של שקט. ארבע דקות וחצי של שליטה בזמן ובגוף. ארבע דקות וחצי שהייתי מצליח להביא את הים לבריכה. עצרתי, חיפשתי משהו להיאחז בו. חיפשתי מישהי להיאחז בה. הבנתי שאני צריך להביא את הים, בדיוק כמו לפני הרבה שנים. חיפשתי גל."},{"t":"p","x":"את גל הכרתי בדרום אמריקה כשהייתי בן 23. חרשנו את מקסיקו ביחד במשך שלושה חודשים על האופנוע. לפעמים היא חיבקה אותי כל כך חזק, שהייתי צריך לעצור את הנשימה. כשעזבתי את מקסיקו בדרך לקוסטה ריקה, גל החליטה שהיא חוזרת לארץ. המפגשים האלו בין אנשים שרק התחילו את הטיול, לאלו שמסיימים. נפרדנו ביום שני בערב בשדה התעופה. בכינו נורא, והבטחתי לה שנהיה בקשר ברגע שאחזור לארץ. ניסיתי להרגיע את הגלים באותו הלילה, אבל כמעט טבעתי בדמעות של עצמי."},{"t":"p","x":"שלוש דקות וחצי מתחת למים, טובע בתוך הגוף של עצמי. בתוך הרעש השקט הזה של דפיקות הלב האיטיות, פתאום שמעתי אותה צועקת אלי. צועקת עלי. ניסיתי להבין מה גל אומרת אבל לא הצלחתי להפריד את המילים מהמים. ידעתי שיש לי מספיק אוויר לניסיון אחרון כדי לצאת החוצה. לקחתי נשימה עמוקה."},{"t":"p","x":"התעוררתי בבהלה. מנסה לפתוח את העינים ללא הצלחה. מרגיש כאילו העפעפיים שלי דבוקים כמו איזו דלקת עיניים קשה. לא כל כך ברור לי איפה אני, אבל די בטוח שאני כבר לא במים. כנראה איבדתי את ההכרה, חושב לעצמי. רעשים מוזרים במקום השקט העוברי. לאט לאט אני מצליח לפתוח את עין ימין. מסתנוור מהאור הלבן. רואה את אמא שלי יושבת לידי ומבין שאני בבית החולים. תחושת הזמן אבדה לי לגמרי."},{"t":"p","x":"נורא מגרד לי באף, אבל אני לא מצליח למצוא את היד. איזו תחושה מוזרה. מצד שני, אני גם לא מצליח למצוא את הלשון. הפה שלי נורא יבש. אמא שלי שקועה בטלפון, לא נראה לי שהיא שמה לב שהתעוררתי ואני לא מצליח לקרוא לה. פתחתי את עין שמאל. פתאום שומע צעקה חזקה, אבל לא מצליח לחבר את הקול והמילים, הכל מתערסל לי בראש באיזה צד של המוח שלא הרגשתי אף פעם. הדמות האפורה שמשמאלי לאט לאט מתבהרת. אני עייף. עוצם את העיניים ומרגיש מלא אנשים מתאספים מסביבי ומדברים. בליל של קולות וצלילים שאני לא מצליח להפריד. אני ממש צמא. החושך הזה עושה לי טוב. עוזר לי לנטרל את כל האור שנכנס לי לתוך המוח דרך העיניים. הקולות שזורמים ולא נעצרים עדיין מפריעים לי. אני מנסה לבודד את הרעשים ולהבין מה קורה מסביבי ללא הצלחה. רק קול אחד מצלצל לי מוכר. מרגיע. קול שאני נאחז בו כמו סולם. מנסה לטפס עליו החוצה מתוך העולם שאני שקוע בתוכו."},{"t":"p","x":"\"גל!\" אני מנסה לקרוא לה, אבל הקול לא יוצא לי מהפה. אני מנסה שוב לפתוח את העיניים ושומע את כל החדר משתתק. אמא שלי בוכה וכנראה מחבקת אותי. העיניים שלי בוהות קדימה, אני מנסה להזיז אותן לצדדים ולא מצליח. גל עומדת לפני ביחד עם עוד כמה רופאים. \"אתה שומע אותי יוני?\" היא שואלת אותי. \"אם כן תלחץ לי את היד, או תמצמץ\"."},{"t":"p","x":"עצמתי עיניים.","c":"line"},{"t":"p","x":"הרגעתי את הגלים של הים ואיתם את קצב הלב שלי.","c":"line"},{"t":"p","x":"עצרתי את הנשימה לחמש דקות וחצי."}]},
  {"id":"roni","t":"סוף החורף של רוני","s":"","p":68,"kind":"סיפור","blocks":[{"t":"p","x":"הלכתי בין העצים, רגליים יחפות שוברות עלים יבשים שצנחו לקרקע אחרי הסופה האחרונה."},{"t":"p","x":"כמה קרני אור מהירח מפלחות את האוויר הקר ומאירות את האדמה."},{"t":"p","x":"הוא עמד שם לבד, מביט אל הנהר מבעד לסבך."},{"t":"p","x":"נעצרתי. רציתי שגם הרגע הזה ייעצר."},{"t":"p","x":"הטפטים הכחולים שמאחורי המיטה התחילו להתקלף, המוזיקה ניגנה ברמקול של הטלפון באיכות של תקליט שרוט."},{"t":"p","x":"שכבתי לרוחב עם הרגליים מחוץ לשמיכה."},{"t":"p","x":"דחפתי את הראש עמוק לכרית וניסיתי להיאחז בשאריות הבושם שלו."},{"t":"p","x":"הוא כבר לא שכב שם."},{"t":"p","x":"תמיד ידעתי שתומר ימות לפני."},{"t":"p","x":"ולמרות שידעתי לא עשיתי עם זה כלום. המשכתי תמיד לריב ולהתווכח."},{"t":"p","x":"אפילו בלילה כשממש היה קר והוא גנב לי את כל השמיכה הייתי מעירה אותו ונוזפת שלא השאיר לי שמיכה. ותומר, כמו תמיד, היה פותח חצי עין, מכסה אותי טוב טוב, שם את היד שלו עלי ומעביר אלי את כל החום שהייתי צריכה."},{"t":"p","x":"היינו הולכים ביחד בטיולי הלילה שלנו בחורשה, והוא היה מחזיק לי את היד ברגע שהיתה מתחילה קצת רוח. אני לא הייתי מחזיקה בחזרה."},{"t":"p","x":"זה לא היה זמן לשינוי, זו לא היתה אשמתי, ועדיין הוא הלך בלי שהייתי מוכנה באמת למרות שתמיד ידעתי."},{"t":"p","x":"איך יכולתי להסביר לו שזו האהבה שלי, שאין לי אחרת, שהייתי מעירה אותו רק כדי להסתכל עוד שנייה בעיניים העמוקות שלו לפני שהייתי יכולה להרדם, לפני שהחלומות הרעים היו עוטפים אותי מבפנים."},{"t":"p","x":"איך יכולתי להסביר לו שהיד שלו חיברה את הרגליים שלי לקרקע, שבלעדיו הייתי כבר מזמן מתעופפת עם משב הרוח הראשון."},{"t":"p","x":"הייתי צריכה את תומר, לא אדע לעולם אם תומר היה צריך אותי."}]},
  {"id":"tomer","t":"חברה של תומר","s":"","p":70,"kind":"סיפור","blocks":[{"t":"p","x":"נשכבתי על האדמה, עדיין מדמם ללא הפסקה. רוני רצה לחפש עזרה לפני חצי שעה, או שעה, הזמן עובר לי לאט ואז מהר, ושוב לאט. אני מרגיש את הדופק בכל הגוף, הנשימה איטית וההכרה עוזבת לאט את הגוף אבל אני תופס אותה חזרה רגע לפני. עשר בלילה. מי היה מאמין שככה היום הזה יתגלגל."},{"t":"p","x":"אילו מחשבות מוזרות עוברות לך בראש ברגעים כאלו של לבד. תמיד חושבים שתצטער על דברים שלא עשית, תיזכר באהבות ובמשפחה ובכלל, תחשוב שהיה יכול להיות יותר. אבל אני, אני הייתי מוכן ללכת. אמנם בן 24, אבל אחרי כזה יום שהכל חזר אלי, הייתי מוכן. איזו הרגשה מוזרה."},{"t":"p","x":"חשבתי על רוני, רצה בפאניקה, מלאה בדם שלי. מסכנה, חשבתי לעצמי, איזו טראומה אני משאיר לה. אף אחד לא מתייחס לחברות של..."},{"t":"p","x":"תפסתי את הנשמה בחצי נשימה."},{"t":"p","x":"זה יותר כואב ממה שחשבתי."},{"t":"p","x":"\"תומר!\""},{"t":"p","x":"שמעתי את רוני צועקת מרחוק, בטח לא זוכרת איך למצוא אותי בין כל העצים."},{"t":"p","x":"חרצתי לב קטן עם האצבעות באדמה הרטובה."},{"t":"p","x":"היה לה ריח של לבנון."},{"t":"p","x":"סחטתי את ההדק שוב."}]},
  {"id":"havtachot","t":"הבטחות","s":"","p":72,"kind":"סיפור קצר","blocks":[{"t":"time","x":"22:30"},{"t":"p","x":"הצחוק של הילדים שרואים טלוויזיה בסלון מזדחל לתוך השקט, האוויר זז קלות, והריח של הים מנסה להתגבר על עשן הסיגריה. מנסה לרוקן לי את המחשבות לתוך החושך שבחוץ."},{"t":"p","x":"ערב ראש השנה. כל הרחוב מריח מהתחלות חדשות ומקמינים ששורפים זכרונות ישנים."},{"t":"time","x":"22:32"},{"t":"p","x":"הודעה מאשתי קופצת על המסך של הטלפון \"בוא למיטה, אני מפחדת שהחושך יבלע אותך\"."},{"t":"p","x":"היא תמיד שם, מחכה לי. לא מבין איך היא יכולה לסבול. אותי. אותנו."},{"t":"time","x":"23:45"},{"t":"p","x":"הקופסה ריקה. איך תמיד חסרה לי הסיגריה האחרונה."},{"t":"time","x":"23:56"},{"t":"p","x":"חם לי בגב כשהיא מחבקת אותי מאחורה. נצמדת אלי חזק חזק, כאילו מנסה להתחבא מהשדים של הלילה. אבל השדים שחורים מתמיד. אני רוצה לחבק אותה חזרה, אבל אני לא יכול."},{"t":"time","x":"00:01"},{"t":"p","x":"שנה חדשה."},{"t":"time","x":"6:23"},{"t":"p","x":"מכבה את השעון המעורר לפני שהוא יצלצל. מתלבש בחושך ומסובב את המנעול של הדלת בשקט. מגניב מבט אל הסלון ההפוך, כריות על הרצפה, שאריות שוקו בכוסות."},{"t":"time","x":"7:40"},{"t":"p","x":"מסובב את המפתח אצלה בדירה הקטנה שבחיפה."},{"t":"time","x":"7:42"},{"t":"p","x":"מפר הבטחה של שנה חדשה."}]},
  {"id":"hachlatot","t":"החלטות","s":"","p":74,"kind":"סיפור קצר","blocks":[{"t":"p","x":"ישבתי בבר בקצה הרחוב, משחק בתחתית של כוס הבירה. מהרהר אם אני מצטער על ההחלטה שלקחתי."},{"t":"p","x":"לפני שעה הנחתי את העצב על השידה שליד המיטה שלה. ידעתי שהיא תמצא אותו כשתחזור הביתה."},{"t":"p","x":"השארתי את המזגן דולק, כמו שהיא אוהבת. שהטמפרטורות ינזלו ממנה ברגע שהיא תפתח את הדלת."},{"t":"p","x":"תמיד היא היתה יותר חמה ממני. לא משנה כמה הייתי מנסה לקרר אותה. לאורך השנים התרגלתי לכל הכוויות שהיא גרמה לי. חלקן לא החלימו מעולם. את האחרונה שעל יד ימין קיבלתי בשבוע שעבר באמצע הלילה כשהיא נכנסה מתנדנדת אחרי יציאה עם חברות. היא נכנסה למיטה, מריחה מעשן של ווג מנטה. מסובבת אלי את הגב, נותנת לי מכה קטנה עם המרפק, \"חבק אותי!\" ואני מחבק ושם לב שהיא בלי החזייה שיצאה איתה מהבית. כוויה."},{"t":"p","x":"\"עוד סטלה בבקשה\"."},{"t":"p","x":"מביט לצד השני של הרחוב."},{"t":"p","x":"אמנם היא הזהירה מראש שהיא רק עוברת כאן לרגע, אבל לא הנחתי שתתן לאותו רגע כל כך הרבה זמן. תוהה לעצמי אם באמת רק נתקלה בי או שאכן הייתי אבן דרך."},{"t":"p","x":"\"בבקשה. שליש סטלה\"."},{"t":"p","x":"אף פעם לא הייתי איש של חצי. אני שותה את הבירה לאט, שונא שהיא מתחממת לי."},{"t":"p","x":"את כל הרגעים שלנו הפכת לשלך. התרגלתי לזה יחסית מהר, נתתי לך להנות מהם. את כל היציאות שלנו שכחת אבל אני זכרתי. הכל. כל פרט ופרט מהן, איך סחבתי אותך הביתה יחפה, שיכורה ומעורפלת. מאושרת."},{"t":"p","x":"שתיתי חצי כוס."},{"t":"p","x":"\"בבקשה, שליש סטלה\". מופתע, הרמתי את הראש למלצרית."},{"t":"p","x":"רואה אותה מולי, מגישה לי את העצב עם תוספת של אושר בצלחת קטנה ליד הבירה."},{"t":"p","x":"\"זה לא מה שהזמנתי\" אמרתי לה."},{"t":"p","x":"\"אבל זה מה שאתה אוהב\" היא ענתה עם חצי חיוך."},{"t":"p","x":"\"חשבון בבקשה\"."}]},
  {"id":"zikaron","t":"זיכרון","s":"","p":76,"kind":"שיר","blocks":[{"t":"st","l":["את המעבר הגס הזה","בין חצי התורן לראשו","אנחנו משמנים בדם של חברים."]},{"t":"st","l":["עם הקו החד הזה","של המניה דיפרסיה הלאומית","אנחנו חותכים נפשות ואומרים אמן."]},{"t":"st","l":["על הגבול הדק הזה","בין דמע לאושר","אנחנו מגדלים ילדים במקום אלו שלקחו לנו."]}]},
  {"id":"andati-osher","t":"ענדתי אושר","s":"","p":77,"kind":"שיר","blocks":[{"t":"st","l":["אוספת את שברי האישיות","שהתרסקה לאלפי חתיכות.","מעמיקה את הקמטים","בעוד קצת אכזבות."]},{"t":"st","l":["המציאות מתערבבת","ביום אחד ארוך.","הלילה אינו נגמר","רק מתחלפות לי השמשות."]},{"t":"st","l":["קמה כל בוקר,","שוטפת את המחשבות","בכיור.","עונדת לי אושר","מתחילה עוד יום."]}]},
  {"id":"hearat-shulayim","t":"הערת שוליים","s":"","p":78,"kind":"אחרית דבר","blocks":[{"t":"p","x":"*המילים הכתובות כאן הינן מסע אישי של התבגרות והתפתחות."},{"t":"p","x":"הן נכתבו מתוך רגעים אישיים שמעורבבים במציאות מדומה. הן לא נכתבו כדי לרצות, או כדי שהקורא.ת יאהב, ישנא, יחבק או יזדהה. הן נכתבו בשבילי, חלקן ברגעים של דמעות ומשבר, חלקן ברגעים של אושר ושמחה. רובן נכתבו לצד אהבתי והשראתי, האישה שתמיד שם לצידי, ועל זה רק רציתי להוסיף מילה אחת שהיא רק בשבילה."},{"t":"p","x":"תודה.","c":"thanks"}]}
];
